def esc(x):return html.escape(str(x),quote=True)
def link(url,label,cls='action'):
 return f'<a class="{cls}" href="{esc(url)}" target="_blank" rel="noopener noreferrer">{esc(label)}</a>'
def source(key,label='查核來源'):return link(S[key][1],label)
def nav(q,label='NAVER 地圖'):return link('https://map.naver.com/p/search/'+quote(q),label,'action primary')
def actions(q=None,src=None):return '<div class="actions">'+(nav(q) if q else '')+(''.join(source(k) for k in src) if src else '')+'</div>'
def badges(items):return '<div class="meta">'+''.join(f'<span class="badge {c}">{esc(t)}</span>' for t,c in items)+'</div>'
def stop(time,title,text,facts=(),q=None,src=None,extra='',kind=''):
 return f'<article class="stop {kind}"><div class="stop-time">{time}</div><div class="stop-main"><h3>{title}</h3><p>{text}</p>{badges(facts)}{extra}{actions(q,src)}</div></article>'
def side(title,items,warn=False):
 return f'<section class="side-card {"paper emergency" if warn else ""}"><h3>{title}</h3><ul>'+''.join(f'<li>{x}</li>' for x in items)+'</ul></section>'
def shops(items):
 return '<div class="shop-grid">'+''.join(f'<section class="shop-pick"><span class="shop-type">{cat}</span><h4>{name}</h4><p>{desc}</p>{actions(q,[src] if src else None)}</section>' for cat,name,desc,q,src in items)+'</div>'
def detail(title,body):return f'<details><summary>{title}</summary><div class="details-body">{body}</div></details>'
def table(head,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join(f'<th scope="col">{c}</th>' for c in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'

