d3['stops']=d3['stops'][:5]+[
stop('14:30–15:15','聖水 → 蠶室｜不再另跑 COEX','聖水站搭 2 號線往建大入口、江邊、蠶室方向，在蠶室站下車。含回車站、等車與找路抓 40–45 分。先看劇院地圖，夏洛特劇院靠樂天世界／樂天世界飯店一側，不是樂天音樂廳，也不是 COEX。',[('下午提早進劇院所在區','ok'),('地鐵預算 ₩1,550–1,900／人','')],q='샤롯데씨어터',src=['frozen']),
stop('15:15–16:30','蠶室室內休息・少量逛街','在蠶室站連通的百貨／商場範圍找有座位的咖啡館，先坐 45–60 分。剩下時間只逛一個樓層；不要加樂天世界遊樂園、水族館或 Seoul Sky。商場与劇院並非同一入口，晚餐前先存好步行路線。',[('咖啡估 ₩7,000–12,000／人',''),('商場內移動也要抓時間','')],q='잠실역 카페'),
stop('16:45–17:45','演出前晚餐｜蠶室站周邊熱定食','在百貨／商場一般對外餐飲區找有座位的韓式定食、湯飯或日式麵飯，預留 ₩20,000–35,000／人。這餐不排需久候的名店，也不選樂天世界遊樂園內需入園票的餐廳。若 17:15 還沒入座，立刻換快餐；餐後先上洗手間。',[('17:45 吃完','must'),('不把燒肉排在演出前','')],q='잠실역 한식',kind='dining-stop'),
stop('17:45–18:30','走到夏洛特劇院・取票與確認座位','導航 샤롯데씨어터，地址 서울 송파구 올림픽로 240。從用餐處到劇院入口至少預留 20–30 分；第一次來以 18:30 抵達為目標。攜帶訂購人護照、訂單與平台要求的付款證明；購票時就核對英文姓名和取票規定。',[('開演前 60 分到場','must'),('2 人連號座位','')],q='샤롯데씨어터',src=['frozen']),
stop('19:30–21:45<br>目標場次','《Frozen 冰雪奇緣》韓文版音樂劇','NOL 官方總檔期為 2026/8/13–2027/3/1；現行週四一般 19:30，預留 135 分含中場 20 分。這表示「档期合適」，不等於 1/7 已開賣或保證有票。熟悉電影的故事與歌曲，對不懂韓文的人較容易跟上；中文字幕／英文字幕未確認，先按無字幕準備。',[('指定日售票待查・未購','check'),('大型劇院音樂劇','ok'),('不得以 NANTA 當同一類替代','')],src=['frozen','frozentime'],extra=table(['座位','現行每人全價','兩人合計','怎麼選'],[('A','₩90,000','₩180,000','預算優先；依座位圖確認距離与遮擋'),('S・建議起點','₩130,000','₩260,000','先選視野完整與連號，不搶最前排'),('R・舒適升級','₩160,000','₩320,000','適合把音樂劇當旅行重點'),('VIP','₩190,000','₩380,000','喜歡近距離表情再加價；不保證一定最好視野')])+detail('購票流程與看戲禮儀','<p>使用官方連出的 NOL World 等正式售票入口，先看 2027/1/7 是否已開放選日，再选 2 張連號、核對卡司／字幕／退票費。沒開賣就保留日程，不能說已售完。開演前收手機，不偷拍或錄影；飲食与遲到入場依劇場規定。此規劃不代下單。</p>')),
stop('21:45–23:00','散場回明洞｜今晚不再加夜景','出場與走回蠶室站抓 15–20 分。2 號線往蠶室渡口、新川方向不在本次回程建議；主選往江邊、聖水、往十里、乙支路入口方向，下車步行回飯店，整段預留約 60–75 分。當日查看末班車，若不想走地下長路，搭合法計程車，預算 ₩30,000–50,000／車，塞車／夜間費另計。',[('先查末班車，不賭最後一班','must'),('隔天古蹟可晚一點開始','')]),
stop('沒票時替換','COEX 星空圖書館，或《洗衣服》小劇場音樂劇','若 1/7 無合適座位，先找同檔期的 1/6 或 1/8，並交換完整下午＋晚上行程。想保留聖水主線又不看戲，可 14:30 改往三成 COEX，15:15 星空圖書館、17:30 晚餐、19:30 回房。另一部《洗衣服 Laundry》檔期也涵蓋旅行，但在大學路、韓文對白較多，必須整段換區，不能直接把蠶室地點沿用。',[('不是同晚看兩部','must'),('備案價格與交通見活動區','')],src=['coex','laundry'])]
d3['aside']=[side('今天真正的優先序',['1. 音樂劇與取票緩衝。','2. 午餐、提前晚餐與室內坐下。','3. 聖水最多兩間店，超時先刪購物。','劇場／售票時刻優先於本頁示例。']),side('天候／體力版本',['昨晚沒睡好就取消上午聖水，下午直接到蠶室。','票已買且無法取消時，取消購物也要保住交通緩衝。','劇院可能暫停入場遲到者，不能壓到最後。','音樂劇票另計，S／R 兩人 ₩260,000–320,000。'],True)]
